<script lang="ts">
 import {untrack} from 'svelte';
 import {invalidateAll} from '$app/navigation';
 let {model,t,tenant}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string;tenant:Record<string,any>}=$props();const moduleKeys=['vineyard','harvest','cellar','blends','lab','bottling','hygiene','costing','assistant','reports','data'];const initial=untrack(()=>({settings:model.settings[0],timezone:tenant.timezone,mode:tenant.mode}));let country=$state(initial.settings?.country??'DE'),region=$state(initial.settings?.region??''),timezone=$state(initial.timezone),mode=$state(initial.mode),retention=$state(initial.settings?.retention_days??3650),modules=$state<string[]>(initial.settings?.modules?.length?initial.settings.modules:moduleKeys),ack=$state(false),busy=$state(false),message=$state('');
 async function save(){busy=true;try{const res=await fetch('/api/settings',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({country,region,timezone,mode,retention_days:retention,modules,expected_version:model.settings[0]?.version,authority_acknowledged:ack})});message=res.ok?t('saved'):t((await res.json()).message);if(res.ok)await invalidateAll();}finally{busy=false;}}
</script>
<section class="card"><h2>{t('winerySettings')}</h2><form onsubmit={(e)=>{e.preventDefault();save();}}><div class="grid"><label>{t('country')}<select bind:value={country}>{#each ['DE','FR','IT','AT','CH','GB','US'] as c}<option value={c}>{c}</option>{/each}</select></label><label>{t('region')}<input bind:value={region} maxlength="160" /></label><label>{t('timezone')}<input bind:value={timezone} required /></label><label>{t('mode')}<select bind:value={mode}>{#each ['standalone','erp','companion'] as m}<option value={m}>{t(m)}</option>{/each}</select></label><label>{t('retention_days')}<input type="number" bind:value={retention} min="30" max="36500" /></label></div><div class="modules">{#each moduleKeys as m}<label><input type="checkbox" value={m} bind:group={modules} />{t(m)}</label>{/each}</div><p class="muted">{t('authorityHint')}</p><label class="check"><input type="checkbox" bind:checked={ack} required />{t('confirmAuthority')}</label><button disabled={busy||!ack}>{t('save')}</button></form><p role="status">{message}</p></section>
<style>.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin:15px 0}.modules{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.modules label,.check{display:flex;align-items:center}input[type=checkbox]{width:18px;height:18px}.check{margin:20px 0}</style>
